mapper.select:
SELECT db.declare_status as tabFlag, count(1) as count FROM tms_declare_bill db where db.is_deleted = false and db.type = #{code}
${permissionSql}
group by db.declare_status

SELECT db.id, db.source_code as sourceCode, db.code, (select count(distinct dbd.sku_id) from tms_declare_bill_detail dbd where dbd.is_deleted = false and dbd.main_id = db.id) as goodsQty, db.merge_source_id as mergeSourceId, case when db.merge_source_id !='' then true else false end as isMerged, db.declare_status as declareStatus, db.business_type as businessType, db.country, db.country_name as countryName, db.box_qty as boxQty, db.net_weight as netWeight, db.gross_weight as grossWeight, db.declare_date as declareDate, db.declare_type as declareType, db.create_user_name as createUserName, db.create_time as createTime from tms_declare_bill db inner join delivery_declare_detail_mid dddm on db.id = dddm.declare_id and dddm.is_deleted = false where ${params.sqlMap.default} and db.is_deleted = false and db.type = #{params.type}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
db.create_time DESC

SELECT  EXTRACT(year FROM db.declare_date),  EXTRACT(month FROM db.declare_date) as month,
count(1)
from tms_declare_bill db
where db.is_deleted = false

    and  db.declare_status = #{params.declareStatus}


    and  db.type = #{params.type}


    and db.declare_date >= #{params.beginDate}


    and db.declare_date <=  #{params.endDate}



    ${permissionSql}

group by EXTRACT(month FROM db.declare_date), EXTRACT(year FROM db.declare_date)
order by  EXTRACT(year FROM db.declare_date), EXTRACT(month FROM db.declare_date)

select db.id, db.type, dddm.source_code as sourceCode, db.pre_input_no as preInputNo, db.dest_customs as destCustoms, db.sender_id as senderId, db.export_customs_name as exportCustomsName, db.export_date as exportDate, db.declare_date as declareDate, db.receiver_name as receiverName, db.transport_no as transportNo, db.dict_supervision_method as dictSupervisionMethod, db.dict_nature_levy as dictNatureLevy, db.license_no as licenseNo, db.code, db.trading_area as tradingArea, db.to_area as toArea, db.to_port as toPort, db.export_port as exportPort, db.dict_pack_type as dictPackType, db.box_qty as boxQty, db.gross_weight as grossWeight, db.net_weight as netWeight, db.dict_transaction_method as dict_transaction_method, db.remark, db.shipping_fee as shippingFee, db.insurance_fee as insuranceFee, db.other_fee as otherFee, db.country_name as countryName from tms_declare_bill db inner join delivery_declare_detail_mid dddm on db.id = dddm.declare_id and dddm.is_deleted = false where ${params.sqlMap.default} and db.is_deleted = false and db.type = #{params.type} and db.declare_status in
#{item}
ORDER BY
${item.field} ${item.sort}
db.create_time DESC

WITH delivery_notice as ( select declare_id, array_to_string(array_agg(DISTINCT business_code),',') as businessCode, array_to_string(array_agg(DISTINCT source_code),',') as sourceCode, array_to_string(array_agg(DISTINCT from_warehouse_name),',') as fromWarehouseName, array_to_string(array_agg(DISTINCT transfer_warehouse_names),',') as transferWarehouseName, array_to_string(array_agg(DISTINCT sales_org_name),',') as salesOrgName from delivery_declare_detail_mid where is_deleted = false and source_type = 'soDeliveryNotice' group by declare_id ) SELECT db.id, db.declar_confirm_date as declareConfirmDate, db.code, (select count(distinct dbd.sku_id) from tms_declare_bill_detail dbd where dbd.is_deleted = false and dbd.main_id = db.id) as goodsQty, db.declare_status as declareStatus, db.business_type as businessType, db.country, db.country_name as countryName, db.box_qty as boxQty, db.net_weight as netWeight, db.gross_weight as grossWeight, db.declare_date as declareDate, db.declare_type as declareType, db.declar_user_name as declareUserName, db.remark, db.create_user_name as createUserName, db.create_time as createTime, dn.businessCode, dn.sourceCode, dn.fromWarehouseName, dn.transferWarehouseName, dn.salesOrgName from tms_declare_bill db left join delivery_notice dn on db.id = dn.declare_id where ${params.sqlMap.default} and db.is_deleted = false and db.type = #{params.type}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
db.create_time DESC

WITH delivery_notice as ( select declare_id, array_to_string(array_agg(DISTINCT business_code),',') as businessCode, array_to_string(array_agg(DISTINCT source_code),',') as sourceCode, array_to_string(array_agg(DISTINCT from_warehouse_name),',') as fromWarehouseName, array_to_string(array_agg(DISTINCT dest_warehouse_name),',') as destWarehouseName, array_to_string(array_agg(DISTINCT transfer_warehouse_names),',') as transferWarehouseName from delivery_declare_detail_mid where is_deleted = false and source_type = 'firstMileDelivery' group by declare_id ) SELECT db.id, db.declar_confirm_date as declareConfirmDate, db.code, (select count(distinct dbd.sku_id) from tms_declare_bill_detail dbd where dbd.is_deleted = false and dbd.main_id = db.id) as goodsQty, db.declare_status as declareStatus, db.business_type as businessType, db.country, db.country_name as countryName, db.box_qty as boxQty, db.net_weight as netWeight, db.gross_weight as grossWeight, db.declare_date as declareDate, db.declare_type as declareType, db.declar_user_name as declareUserName, db.remark, db.create_user_name as createUserName, db.create_time as createTime, dn.businessCode, dn.sourceCode, dn.fromWarehouseName, dn.destWarehouseName, dn.transferWarehouseName from tms_declare_bill db left join delivery_notice dn on db.id = dn.declare_id where ${params.sqlMap.default} and db.is_deleted = false and db.type = #{params.type}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
db.create_time DESC
